def kimi_k3_moe_route_roofline_work(kernel: KernelSpec):
    source = kimi_k3_moe_route_logical_work(kernel)
    rows, experts, topk = (kernel.shape[key] for key in ("rows", "experts", "topk"))
    values, selected = rows * experts, rows * topk
    primitives = {"exp": values, "denominator_add": values, "sigmoid_divide": values,
        "selection_bias_add": values, "selected_sum_add": rows * (topk - 1),
        "selected_weight_divide": selected, "selected_weight_scale": selected}
    flops = sum(count for name, count in primitives.items() if name != "exp")
    return {"mathematical_primitives": primitives, "logical_bytes": sum(
            operand["bytes"] for operand in source["operands"]),
        "demand": {"compute_tensor": 0.0, "compute_vector": 0.0, "compute_reduction": 0.0,
            "compute_fma": float(flops), "compute_sfu": float(values), "compute_alu": 0.0},
        "typed_actions": {"score_negate": values, "biased_top16_ID_selection": selected},
        "source": source["source"], "complete_native_work_bound": False,
        "limitations": source["limitations"] + (
            "mathematical_sigmoid_exp_and_divide_do_not_bind_CUDA_or_torch_instruction_services",)}


def kimi_moe_route_logical_work(kernel: KernelSpec):
    """Unbound Kimi 0.30 grouped routing from BF16 gate logits.

    GateLinear.out_dtype=None takes ReplicatedLinear/F.linear. Routing is
    a separate producer of FP32 weights and INT32 IDs. The fused CUDA path
    promotes each BF16 input to FP32 before scoring; the torch branch scores
    in BF16, selects with FP32 bias, then converts gathered weights/IDs on
    export. Do not price one branch as an observed provider or invent their
    compiler operations from the common mathematical sigmoid/top8 semantics.
    CUDA block/warp FP32 recovery is also distinct: finite inputs alone do
    not prove path equivalence or preservation of the normalized weight sum.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant != "kimi_moe_route"
            or kernel.execution_support != "unsupported" or kernel.launch is not None):
        raise ValueError("Kimi route logical work requires an unbound source contract")
    rows, experts, topk = (kernel.shape[n] for n in ("rows", "experts", "topk"))
    block_path = rows <= 1024
    # The 384/8 tier is outside HighExpertLaneOwnedTopKRange. Both paths
    # call reduceTopK with 12 candidates/lane, not GLM's Sort<8>. The
    # source's size-12 odd-even Batcher network has 42 compare pairs/lane;
    # comparisons/conditional swaps do not bind packed64 instructions.
    cuda_role_uses = [
        {"role": "preprocess_logits", "space": "global", "access": "read",
         "dtype": "bf16", "bytes": rows * experts * 2},
        {"role": "preprocess_bias", "space": "global", "access": "read",
         "dtype": "fp32", "bytes": rows * experts * 4},
        {"role": "selected_weights", "space": "global", "access": "write",
         "dtype": "fp32", "bytes": rows * topk * 4},
        {"role": "selected_ids", "space": "global", "access": "write",
         "dtype": "int32", "bytes": rows * topk * 4},
    ]
    if block_path:
        cuda_role_uses.extend([
            {"role": "preprocessed_unbiased_scores", "space": "shared", "access": "write",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "preprocessed_biased_scores", "space": "shared", "access": "write",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "selection_biased_scores", "space": "shared", "access": "read",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "selected_unbiased_scores", "space": "shared", "access": "read",
             "dtype": "fp32", "bytes": rows * topk * 4},
        ])
    else:
        cuda_role_uses.append(
            {"role": "selected_bias_recovery", "space": "global", "access": "read",
             "dtype": "fp32", "bytes": rows * topk * 4})
    return {
        "sigmoid_values": rows * experts,
        "bias_selection_additions": rows * experts,
        "id_selection": "biased_sigmoid_grouped_top8",
        "selected_sum_additions": rows * (topk - 1),
        "selected_weight_normalizations": rows * topk,
        "selected_weight_scales": rows * topk,
        "routed_scaling_factor": kernel.attributes["routed_scaling_factor"],
        "global_unique_operand_bytes": 2 * rows * experts + 4 * experts + 8 * rows * topk,
        "operands": (
            {"role": "logits_role_read", "dtype": "bf16", "elements": rows * experts,
             "bytes": rows * experts * 2, "access": "read"},
            {"role": "correction_bias_role_read", "dtype": "fp32", "elements": rows * experts,
             "bytes": rows * experts * 4, "access": "read"},
            {"role": "selected_weight", "dtype": "fp32", "elements": rows * topk,
             "bytes": rows * topk * 4, "access": "write"},
            {"role": "selected_id", "dtype": "int32", "elements": rows * topk,
             "bytes": rows * topk * 4, "access": "write"}),
        "cuda_source_candidate": {
            "condition": "modular CUDA grouped_topk enabled; BF16 contiguous logits/FP32 bias; n_group=topk_group=1; no runtime binding",
            "kernel": "single_group_topk_block_kernel<384,8>" if rows <= 1024
                      else "single_group_topk_warp_kernel<384,8>",
            "grid": (rows if rows <= 1024 else min(-(-rows // 8), 2048), 1, 1),
            "block": (256, 1, 1),
            # Named source arrays exclude cooperative-groups/compiler
            # scratch. Their size does not bind total shared allocation.
            "named_score_array_bytes_per_cta": 3072 if rows <= 1024 else 0,
            "static_shared_bytes_per_cta": None,
            "launch_assigned": False,
            "numerical_semantics": _single_group_topk_source_numerics(rows <= 1024),
            "finite_input_program": {
                "condition": "all logits/bias and all eight selected scores finite; conditional source accounting only, not observed values or a numerical equivalence predicate",
                "bf16_to_fp32_values": rows * experts,
                "sigmoid_expression": "0.5f * tanhf(0.5f * x) + 0.5f",
                "tanh_calls": rows * experts,
                "sigmoid_scalar_multiplications": 2 * rows * experts,
                "sigmoid_scalar_additions": rows * experts,
                "bias_selection_additions": rows * experts,
                "selected_bias_recovery_subtractions": 0 if block_path else rows * topk,
                "selected_weight_recovery": "shared unbiased score" if block_path else "selected biased score minus reread bias",
                "initial_score_pack_uint64_values": rows * experts,
                "lane_sort_candidates": 12,
                "lane_sort_uint64_comparisons": rows * 32 * 42,
                "warp_max_uint64_reductions": rows * topk,
                "warp_sum_fp32_reductions": rows,
                "warp_reduction_lanes": 32,
                "selected_denominator_epsilon_additions": rows * topk,
                "selected_scale_divisions": rows * topk,
                "selected_output_multiplications": rows * topk,
                "global_unique_operand_bytes": 2 * rows * experts + 4 * experts + 8 * rows * topk,
                "role_uses": tuple(cuda_role_uses),
                "limitations": (
                    "nonfinite branches data dependent; finite program not generic execution coverage",
                    "source tanhf is not bound to one hardware SFU instruction",
                    "packed64 comparisons, conditional swaps/updates, shuffles and reductions are not dynamic compiler instruction counts",
                    "named source shared arrays exclude cooperative-groups/compiler scratch; total static allocation remains unbound",
                    "role-use bytes and repeated bias reads do not imply transactions, bank behavior or cache/DRAM residency",
                    "local CUDA12.2 full-TU and host registration evidence is not selected H200 provider/runtime binding"),
                "demand": None, "seconds": None,
            },
        },
        "limitations": (
            "mathematical_semantics_not_actual_modular_monolithic_provider_selection",
            "CUDA FP32 scoring vs torch BF16 scoring/weights/export conversions are distinct source programs",
            "role_reads_not_unique_addresses_or_observed_dram",
            "temporary_buffers_sort12_uint64_reductions_tanhf_and_compiler_services_unbound",
            "actual_provider_launch_padding_and_runtime_unbound"),
        "demand": None, "seconds": None,
    }


def _dsv32_sm90_selection_source_program(rows):
    """Typed source events for GLM's E256/K8 lane sort and reductions.

    moeTopKFuncs.cuh uses Sort<8> and cg::reduce on a static 32-lane tile.
    In CUDA12.2 reduce.h, REDUX accepts integral values of at most 4 bytes:
    uint64 greater and float plus both use coalesced_reduce.h's five XOR
    stages. helpers.h slices each uint64 shuffle into two 32-bit words.
    These are source events before compiler optimization, not issue counts.
    """
    lanes, candidates, topk, stages = 32, 8, 8, 5
    max_lane_steps = rows * topk * lanes * stages
    sum_lane_steps = rows * lanes * stages
    evictions = rows * (topk - 1)
    return {
        "condition": "vLLM0.30 E256/K8 non-hierarchical source with CUDA12.2 cooperative_groups static tile32 on SM90; not an observed provider",
        "source": ("moeTopKFuncs.cuh:TopKRedType/Sort<8>/reduceTopK",
                   "cooperative_groups/details/reduce.h:_redux_dispatch",
                   "cooperative_groups/details/coalesced_reduce.h:static-tile coalesced_reduce",
                   "cooperative_groups/details/helpers.h:shuffle_dispatch"),
        "key_dtype": "uint64", "lane_candidates": candidates,
        "initial_key_pack_calls": rows * lanes * candidates,
        "bitonic_compare_exchange_uint64": rows * lanes * 24,
        "warp_max_reductions": rows * topk, "warp_reduction_stages": stages,
        "warp_max_lane_compare_select_uint64": max_lane_steps,
        "warp_max_shuffle_word32": 2 * max_lane_steps,
        "head_equality_uint64": rows * (topk - 1) * lanes,
        # Each lane's keys retain expert_id % 32 == lane. The packed
        # inverse-index bits therefore make the 32 lane heads unique,
        # even when floating scores tie. Exactly one lane evicts per round.
        "head_uniqueness": "inverse-index low five bits identify the originating lane",
        "winning_lane_evictions": evictions,
        "shifted_keys_after_evictions": evictions * (candidates - 1),
        "sentinel_key_pack_calls": evictions,
        "source_unpack_calls": rows * topk * lanes,
        "weight_sum_lane_add_fp32": sum_lane_steps,
        "weight_sum_shuffle_word32": sum_lane_steps,
        "uint64_redux32_supported": False, "float_redux32_supported": False,
        "typed_primitive_resource_mapping_complete": False,
        "compiler_instruction_counts_or_dynamic_issue_bound": False,
        "demand": None, "seconds": None,
    }


def attention_state_merge_roofline_work(kernel: KernelSpec):
    """Useful real-arithmetic LSE merge, with an explicit empty-prefix domain.

    vLLM0.30 attention/ops/merge_attn_states.py and the corresponding CUDA
    source normalize two partial sums, then combine their BF16 outputs.
    The SGLang empty-prefix domain declares zero O/-infinity LSE and a
    nonempty suffix; its source normalizes infinities before the same merge.
    Repeated per-pack scale work, other exceptional values, scratch and launch are not
    bound. It must not be used to claim the CUDA instruction program.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant != "vllm_attention_state_merge"
            or kernel.launch is not None or kernel.execution_support != "unsupported"):
        raise ValueError("attention state merge requires its unbound mathematical contract")
    rows = kernel.shape["rows"] * kernel.shape["heads"]
    elements = kernel.shape["element_count"]
    output_lse = kernel.attributes["output_lse"]
    payloads = {"prefix_output": elements * 2, "suffix_output": elements * 2,
        "prefix_lse": rows * 4, "suffix_lse": rows * 4,
        "merged_output": elements * 2, "merged_lse": rows * 4 if output_lse else 0}
    # Two subtracts, a sum and two divisions per normalizer; each output
    # element needs two multiplies and an add. Optional LSE adds log+max.
    flops = 5 * rows + 3 * elements + (rows if output_lse else 0)
    return {"logical_bytes": sum(payloads.values()), "payload_bytes": payloads,
        "arithmetic_flops": flops, "exp_operations": 2 * rows,
        "log_operations": rows if output_lse else 0,
        "typed_actions": {"maximum": rows,
            **({"normalize_infinite_lse": 2 * rows} if kernel.attributes["mathematical_program"] ==
                "sglang_0_5_19_empty_prefix_lse_merge_flops_bytes_v1" else {})},
        "demand": {"compute_tensor": 0.0, "compute_vector": 0.0, "compute_reduction": 0.0,
            "compute_fma": float(flops), "compute_sfu": float(2 * rows + (rows if output_lse else 0)),
            "compute_alu": 0.0}, "complete_native_work_bound": False,
        "limitations": ("real_attention_states_not_rounded_CUDA_equivalence",
            "logical_role_payload_not_repeated_pack_reads_or_observed_DRAM",
            "nonempty_states_or_declared_zero_O_negative_infinity_prefix_with_nonempty_suffix",
            "other_empty_branches_conversions_compiler_scratch_and_provider_unbound")}


def biased_sigmoid_topk_roofline_work(kernel: KernelSpec):
    """Useful real-arithmetic routing, separate from CUDA/torch numerics.

    GroupedTopKRouter uses sigmoid scores plus bias to select IDs, gathers
    unbiased scores and normalizes/scales the selected weights. This program
    counts public role-use bytes and ideal mathematical arithmetic, not sort
    instructions, physical DRAM transactions or an actual provider branch.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant not in ("dsv32_moe_route", "kimi_moe_route")
            or kernel.execution_support != "unsupported" or kernel.launch is not None
            or kernel.attributes["mathematical_program"] != "biased_sigmoid_topk_flops_bytes_v1"):
        raise ValueError("biased sigmoid routing requires its explicit unbound mathematical program")
    roles = (dsv32_moe_route_logical_work(kernel) if kernel.variant == "dsv32_moe_route"
        else kimi_moe_route_logical_work(kernel))
    rows, experts, topk = (kernel.shape[key] for key in ("rows", "experts", "topk"))
    values, selected = rows * experts, rows * topk
    # sigmoid(x)=1/(1+exp(-x)); negation is a separately recorded typed
    # action, not an FP32 add/mul. Mathematical division counts as one FLOP
    # and exp as one ideal SFU operation, without asserting ISA lowering.
    primitives = {"exp": values, "denominator_add": values, "sigmoid_divide": values,
        "selection_bias_add": values, "selected_sum_add": rows * (topk - 1),
        "selected_weight_divide": selected, "selected_weight_scale": selected}
    flops = sum(count for name, count in primitives.items() if name != "exp")
    operands = roles["operands"]
    return {"mathematical_program": kernel.attributes["mathematical_program"],
        "mathematical_primitives": primitives, "arithmetic_flops": flops,
        "typed_actions": {"score_negate": values, "biased_topk_ID_selection": selected},
        "operands": operands, "logical_bytes": sum(port["bytes"] for port in operands),
        "demand": {"compute_tensor": 0.0, "compute_vector": 0.0, "compute_reduction": 0.0,
            "compute_fma": float(flops), "compute_sfu": float(values), "compute_alu": 0.0},
        "complete_native_work_bound": False, "numerical_equivalence_asserted": False,
        "limitations": ("useful_real_arithmetic_not_CUDA_or_torch_rounded_program",
            "biased_selection_comparisons_ID_construction_and_negation_not_arithmetic_FLOPs",
            "source_tensor_temporaries_sort_scratch_and_physical_transactions_unbound",
            "bias_role_reads_not_unique_parameter_objects_or_observed_DRAM",
            "exp_and_division_are_mathematical_operations_not_bound_compiler_services",
            "actual_provider_launch_runtime_and_normal_capacity_not_accepted")}


def dsv32_moe_route_logical_work(kernel: KernelSpec):
    """GLM mathematical routing roles with separate source program semantics.

    GroupedTopKRouter/grouped_topk selects by sigmoid(logits)+FP32 bias,
    mathematically uses unbiased sigmoid weights, normalizes the selected
    eight weights and applies the config scaling factor. This does not
    assert CUDA block/warp or torch finite-precision equivalence. Both branches
    return FP32 weights and INT32 IDs. A separate conditional CUDA source
    program records known finite-input math and role uses, including the
    warp path's rounded bias-subtraction recovery; finiteness alone does not
    prove recovery equality or scaling-factor weight-sum preservation.
    It does not bind a provider,
    compiler service, memory transaction model, demand or duration.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant != "dsv32_moe_route"
            or kernel.execution_support != "unsupported" or kernel.launch is not None):
        raise ValueError("GLM route logical work requires an unbound source contract")
    rows, experts, topk = (kernel.shape[n] for n in ("rows", "experts", "topk"))
    block_path = rows <= 1024
    # These are source role-use bytes, not instructions or cache transactions.
    # The E=256/K=8 tier disables HighExpertLaneOwnedTopKRange; only warp0
    # selects on the block path. Sort<8> compares 4 pairs in each of 6 stages
    # on all 32 participating lanes, then reduceTopK issues 8 warp maxima.
    cuda_role_uses = [
        {"role": "preprocess_logits", "space": "global", "access": "read",
         "dtype": "fp32", "bytes": rows * experts * 4},
        {"role": "preprocess_bias", "space": "global", "access": "read",
         "dtype": "fp32", "bytes": rows * experts * 4},
        {"role": "selected_weights", "space": "global", "access": "write",
         "dtype": "fp32", "bytes": rows * topk * 4},
        {"role": "selected_ids", "space": "global", "access": "write",
         "dtype": "int32", "bytes": rows * topk * 4},
    ]
    if block_path:
        cuda_role_uses.extend([
            {"role": "preprocessed_unbiased_scores", "space": "shared", "access": "write",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "preprocessed_biased_scores", "space": "shared", "access": "write",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "selection_biased_scores", "space": "shared", "access": "read",
             "dtype": "fp32", "bytes": rows * experts * 4},
            {"role": "selected_unbiased_scores", "space": "shared", "access": "read",
             "dtype": "fp32", "bytes": rows * topk * 4},
        ])
    else:
        cuda_role_uses.append(
            {"role": "selected_bias_recovery", "space": "global", "access": "read",
             "dtype": "fp32", "bytes": rows * topk * 4})
    return {
        "sigmoid_values": rows * experts,
        "bias_selection_additions": rows * experts,
        "id_selection": "biased_sigmoid_grouped_top8",
        # grouped_topk_kernels.cu SigmoidBiasTiers chooses <256,8>.
        # launch() selects one 256-thread block/token through 1024 rows;
        # above it WarpTopKLaunchConfig<256> packs eight token warps/CTA
        # and caps the grid at 1024 blocks. These are conditional source
        # facts, never a launch assigned to this unbound KernelSpec.
        "cuda_source_candidate": {
            "condition": "CUDA with VLLM_USE_FUSED_MOE_GROUPED_TOPK enabled; FP32 contiguous logits/bias; n_group=topk_group=1",
            "kernel": "single_group_topk_block_kernel<256,8>" if rows <= 1024
                      else "single_group_topk_warp_kernel<256,8>",
            "grid": (rows if rows <= 1024 else min(-(-rows // 8), 1024), 1, 1),
            "block": (256, 1, 1),
            # Named source arrays exclude cooperative-groups/compiler
            # scratch. Their size does not bind total shared allocation.
            "named_score_array_bytes_per_cta": 2048 if rows <= 1024 else 0,
            "static_shared_bytes_per_cta": None,
            "launch_assigned": False,
            "numerical_semantics": _single_group_topk_source_numerics(block_path),
            "selection_compute": "packed uint64 compare/sort and cooperative-groups reductions; compiler service unbound",
            "finite_input_program": {
                "condition": "all logits/bias and all eight selected scores finite; conditional source accounting only, not observed values or a numerical equivalence predicate",
                "sigmoid_expression": "0.5f * tanhf(0.5f * x) + 0.5f",
                "tanh_calls": rows * experts,
                "sigmoid_scalar_multiplications": 2 * rows * experts,
                "sigmoid_scalar_additions": rows * experts,
                "bias_selection_additions": rows * experts,
                "selected_bias_recovery_subtractions": 0 if block_path else rows * topk,
                "selected_weight_recovery": "shared unbiased score" if block_path else "selected biased score minus reread bias",
                "score_pack_uint64_values": rows * experts,
                "lane_sort_uint64_comparisons": rows * 32 * 24,
                "warp_max_uint64_reductions": rows * topk,
                "warp_sum_fp32_reductions": rows,
                "warp_reduction_lanes": 32,
                "selection_program": _dsv32_sm90_selection_source_program(rows),
                "selected_denominator_epsilon_additions": rows * topk,
                "selected_scale_divisions": rows * topk,
                "selected_output_multiplications": rows * topk,
                "global_unique_operand_bytes": 4 * (rows * experts + experts + 2 * rows * topk),
                "role_uses": tuple(cuda_role_uses),
                "limitations": (
                    "nonfinite branches data dependent; finite program not generic execution coverage",
                    "source tanhf is not bound to one hardware SFU instruction",
                    "uint64 compare, shuffle, packing, conditional updates and reduction compiler services unbound",
                    "shared capacity and role-use bytes do not imply transactions, bank behavior or residency",
                    "bias role rereads reuse one unique bias object; cache/DRAM service unbound"),
                "demand": None, "seconds": None,
            },
        },
        "selected_sum_additions": rows * (topk - 1),
        "selected_weight_normalizations": rows * topk,
        "selected_weight_scales": rows * topk,
        "routed_scaling_factor": kernel.attributes["routed_scaling_factor"],
        "operands": (
            {"role": "logits_role_read", "dtype": "fp32", "elements": rows * experts,
             "bytes": rows * experts * 4, "access": "read"},
            {"role": "correction_bias_role_read", "dtype": "fp32", "elements": rows * experts,
             "bytes": rows * experts * 4, "access": "read"},
            {"role": "selected_weight", "dtype": "fp32", "elements": rows * topk,
             "bytes": rows * topk * 4, "access": "write"},
            {"role": "selected_id", "dtype": "int32", "elements": rows * topk,
             "bytes": rows * topk * 4, "access": "write"}),
        "limitations": (
            "source_modular_grouped_topk_semantics_not_observed_backend_selection",
            "role_reads_not_unique_footprints_or_observed_dram",
            "group_selection_trees_temporary_buffers_and_torch_conversion_unbound",
            "actual_provider_compiler_launch_padding_and_runtime_unbound",
            "no_rate_or_duration_assigned_to_logical_work"),
    }


def dsv4_short_context_topk_source_work(kernel: KernelSpec):
    """Complete source-level global objects of the simple supplied-output fill.

    This kernel reads only positions and overwrites every active index;
    arange/where values are local SSA, not temporary device tensors.
    Logical work and padded source expressions do not bind GPU issue counts.
    """
    if kernel.kind is not KernelKind.VECTOR or kernel.variant != "dsv4_short_context_topk":
        raise ValueError("short-context source work requires its V4 VECTOR variant")
    rows, width = kernel.shape["seq_len"], kernel.shape["topk_capacity"]
    padded = 1 << (width - 1).bit_length()
    return {"source_symbol": "deepseek_v4._fill_short_context_topk_indices",
        "positions": {"dtype": "int64", "shape": [rows], "read_bytes": 8 * rows, "read_only": True},
        "output": {"dtype": "int32", "shape": [rows, width], "strides_elements": [width, 1],
                   "write_bytes": 4 * rows * width, "supplied_output_pointer": True,
                   "reads_previous_output": False, "writes_sentinels_too": True},
        "program": {"compressed_count": "(position + 1) // 4", "value": "column if column < compressed_count else -1",
                    "store_mask": "column < topk_capacity", "source_vector_width": padded,
                    "logical_position_adds": rows, "logical_compression_divides": rows,
                    "logical_value_comparisons": rows * width, "logical_value_selects": rows * width,
                    "padded_source_value_comparisons": rows * padded},
        "per_call_tensor_allocations": [], "global_tensor_temporaries": [],
        "local_values": ["offsets", "compressed_count", "selected_index_or_sentinel"],
        "actual_compiler_or_runtime_bound": False,
        "scope": "supplied-output source fill; source tensor temporaries only, not register spills, allocator addresses or native instructions"}


def dsv4_moe_route_logical_work(kernel: KernelSpec):
    """Describe pure-text routing roles without selecting a CUDA provider.

    vLLM normal FusedMoE returns FP32 weights and INT32 IDs. Hash routing
    transforms only the six selected logits; ordinary routing transforms all
    experts and uses correction bias only for ID selection. Providers use
    different stable softplus implementations and reduction/selection trees;
    no instruction count, aggregate demand, launch or time is inferred here.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant != "dsv4_moe_route"
            or kernel.execution_support != "unsupported" or kernel.launch is not None):
        raise ValueError("V4 logical route requires an unbound route KernelSpec")
    rows, experts, topk = (kernel.shape[n] for n in ("rows", "experts", "topk"))
    hashed = kernel.attributes["expert_id_selection"] == "hash_table"
    scores = rows * (topk if hashed else experts)
    operands = [
        {"role": "logits_role_read", "dtype": "fp32", "elements": scores,
         "bytes": scores * 4, "access": "read"},
        {"role": "selected_weight", "dtype": "fp32", "elements": rows * topk,
         "bytes": rows * topk * 4, "access": "write"},
        {"role": "selected_id", "dtype": "int32", "elements": rows * topk,
         "bytes": rows * topk * 4, "access": "write"},
    ]
    if hashed:
        operands.extend((
            {"role": "hash_input_id_after_conversion", "dtype": "int32",
             "elements": rows, "bytes": rows * 4, "access": "read"},
            {"role": "hash_table_selected_entries_role_read", "dtype": "int32",
             "elements": rows * topk, "bytes": rows * topk * 4, "access": "read"}))
    else:
        operands.append({"role": "correction_bias_role_read", "dtype": "fp32",
                         "elements": rows * experts, "bytes": rows * experts * 4,
                         "access": "read"})
    return {
        "sqrtsoftplus_values": scores,
        "id_selection": "hash_lookup" if hashed else "biased_top6",
        "selected_sum_additions": rows * (topk - 1),
        "selected_weight_scales": rows * topk,
        "routed_scaling_factor": kernel.attributes["routed_scaling_factor"],
        "operands": tuple(operands),
        "limitations": (
            "pure_text_normal_fused_moe_semantics_not_mega_or_image_routing",
            "conditional_modular_stage_monolithic_fusion_placement_unbound",
            "role_reads_not_unique_footprints_or_observed_dram",
            "provider_softplus_and_topk_reductions_not_instruction_counts",
            "actual_hash_ids_bias_values_padding_and_input_id_conversion_unbound",
            "router_provider_compiler_launch_and_local_services_unbound",
            "no_rate_or_duration_assigned_to_logical_work"),
    }


def mhc_prenorm_logical_work(kernel: KernelSpec):
    """Describe unpriced mHC projection math and typed operands.

    vLLM 0.30 tilelang.py _hc_prenorm_gemm_outputs and its torch reference
    specify x.float() @ fn.t() and x.float().square().sum(-1). Broadcast
    uses the precomputed fn_broadcast[N,H]; regular uses fn[N,hc_mult*H].
    The selected split count describes FP32 output allocation only. These
    logical counts do not establish DeepGEMM execution, traffic or a rate.
    An independently found local SM90 header supplies a conditional padded
    TF32 source program for hc_mult=4, separate from the mathematical work.
    Its host configuration/version selection remains unbound.
    """
    if (kernel.kind is not KernelKind.VECTOR or kernel.variant not in (
            "mhc_prenorm", "mhc_prenorm_broadcast")
            or kernel.execution_support != "unsupported" or kernel.launch is not None):
        raise ValueError("mHC logical prenorm work requires an unbound prenorm KernelSpec")
    hidden, hc_mult = kernel.shape["hidden"], kernel.shape["hc_mult"]
    tokens = kernel.shape["element_count"] // (hidden * hc_mult)
    width = hidden if kernel.variant == "mhc_prenorm_broadcast" else hidden * hc_mult
    mixes = hc_mult * (hc_mult + 2)
    splits = kernel.shape["n_splits"]
    sm90_source = None
    if (kernel.attributes["source_prenorm_backend"] != "tilelang"
            and HWSpec.source_contract_supported("sm90_tf32_hc_prenorm_gemm_impl", kernel.hardware_id) and hc_mult == 4
            and splits <= -(-width // 64)):
        # sm90_tf32_hc_prenorm_gemm.cuh asserts M=64, K=64 and 128
        # math threads. TF32MMASelector admits N=8/16/32/64/128/256;
        # the single-N-tile program needs at least N=32 for 24 outputs.
        # All 64 fragment rows execute MMA and sqrsum work. Descriptor
        # bounds/fill and padded backing storage remain host-config unbound.
        padded_rows = -(-tokens // 64) * 64
        padded_width = -(-width // 64) * 64
        sm90_source = {
            "condition": "audited local sm90_tf32_hc_prenorm_gemm_impl selected with a complete single-N-tile projection and nonempty K partitions; not actual vLLM/provider binding",
            "source_template": "sm90_tf32_hc_prenorm_gemm_impl",
            "input_storage_dtype": "bf16", "weight_storage_dtype": "fp32",
            "matrix_input_format": "tf32", "output_storage_dtype": "fp32",
            "block_m": 64, "block_k": 64, "minimum_complete_block_n": 32,
            "math_threads": 128, "tma_threads": None, "block_threads": None,
            "stages": None, "selected_block_n": None,
            "tensor_descriptor_bounds_and_fill": None,
            "complete_projection_ctas": -(-tokens // 64) * splits,
            "projection_tf32_flops_minimum": 2 * padded_rows * 32 * padded_width,
            "bf16_to_fp32_fragment_values": padded_rows * padded_width,
            "sqrsum_square_multiplications": padded_rows * padded_width,
            "sqrsum_accumulation_additions": padded_rows * padded_width,
            # Two accumulators/thread, each warp_reduce_sum<4> executes
            # two XOR/add steps on all 128 math threads, per split CTA.
            "sqrsum_subwarp_additions": 128 * 2 * 2 * -(-tokens // 64) * splits,
            # tma_copy.cuh defaults multicast=1 and divides the K64 tile
            # into swizzle/sizeof(storage) atoms: one BF16 A atom (64)
            # and two FP32 B atoms (32). Splits partition K blocks once.
            # These are CUTE source calls, not compiled instructions or
            # DRAM transactions; descriptor OOB lanes may supply zeros.
            "tma_load_source_calls": {
                "multicast": 1, "a_inner_atom": 64, "b_inner_atom": 32,
                "a_calls_per_k_block": 1, "b_calls_per_k_block": 2,
                "a_calls": -(-tokens // 64) * -(-width // 64),
                "b_calls": 2 * -(-tokens // 64) * -(-width // 64),
                "actual_instruction_count_bound": False,
                "dram_bytes_bound": False,
            },
            "conversion_storage": "BF16 shared fragment to FP32 registers; this template requires no global FP32 input copy",
            "numerically_equivalent_to_fp32_torch_reference": None,
            "actual_provider_bound": False, "launch_assigned": False,
            "demand": None, "seconds": None,
        }
    return {
        "projection_flops": 2 * tokens * mixes * width,
        "square_operations": tokens * width,
        "unsplit_sum_additions": tokens * max(width - 1, 0),
        "source_prenorm_backend": kernel.attributes["source_prenorm_backend"],
        "conditional_sm90_source_program": sm90_source,
        "operands": (
            {"role": "input", "dtype": "bf16", "shape": (tokens, width),
             "bytes": 2 * tokens * width, "access": "read"},
            {"role": "weight", "dtype": "fp32", "shape": (mixes, width),
             "bytes": 4 * mixes * width, "access": "read"},
            {"role": "projection_partial", "dtype": "fp32", "shape": (splits, tokens, mixes),
             "bytes": 4 * splits * tokens * mixes, "access": "write"},
            {"role": "sqrsum_partial", "dtype": "fp32", "shape": (splits, tokens),
             "bytes": 4 * splits * tokens, "access": "write"},
        ),
        "limitations": (
            "mathematical_projection_and_unsplit_sqrsum_not_instruction_counts",
            "split_reduction_math_priced_by_downstream_norm_stage_not_here",
            "typed_operand_footprints_not_observed_dram_or_repeated_reads",
            "bf16_to_fp32_conversion_and_backend_temporary_storage_unbound",
            "local_sm90_template_not_bound_to_vllm_selected_version_host_config_compiler_or_launch",
            "zero_stage_split_source_validity_unproved_no_conditional_program",
            "no_rate_or_duration_assigned_to_logical_work",
        ),
    }


def mhc_prenorm_roofline_work(kernel: KernelSpec):
    """Logical FP32 arithmetic and typed storage, independent of a launch.

    vLLM kernels/mhc/torch.py evaluates FP32 matmul and square/sum;
    kernels/mhc/tilelang.py::_hc_prenorm_gemm_outputs materializes split
    FP32 projection and sumsq tensors. Count two FLOPs per multiply-and-add
    or square-and-accumulate, including zero-initialized accumulation, as the fused
    mhc_post_prenorm ledger does. The downstream norm owns split merging.

    This is an FP32 arithmetic Roofline against the card's FP32 FMA peak.
    It does not select the conditional TF32 template, price padded MMA
    instructions, or assert native provider/temporary-buffer behavior.
    """
    work = mhc_prenorm_logical_work(kernel)
    width = (kernel.shape["hidden"] if kernel.variant == "mhc_prenorm_broadcast"
             else kernel.shape["hidden"] * kernel.shape["hc_mult"])
    if kernel.shape["n_splits"] > -(-width // 64):
        raise NotImplementedError("mHC prenorm zero-stage split source validity remains unbound")
    demand = {role: 0.0 for role in (
        "compute_tensor", "compute_vector", "compute_reduction",
        "compute_fma", "compute_sfu", "compute_alu")}
    demand["compute_fma"] = float(work["projection_flops"] + 2 * work["square_operations"])
    return {
        "demand": demand,
        "logical_bytes": sum(operand["bytes"] for operand in work["operands"]),
        "logical_work": work,
        "arithmetic_contract": "logical_fp32_fma_peak_not_selected_tf32_or_native_kernel",
        "limitations": (
            "logical_unique_operand_bytes_not_observed_dram_or_temporary_storage",
            "fp32_arithmetic_not_compiler_instructions_or_selected_tf32_program",
            "input_conversion_and_address_control_services_not_instruction_modeled",
            "split_partial_merging_priced_by_downstream_norm_not_here",
            "actual_provider_compiler_launch_and_runtime_unbound"),
    }


def mhc_stage_logical_work(kernel: KernelSpec):
    """Typed global objects and source arithmetic for one mHC stage.

    vLLM 0.30 tilelang_kernels.py mhc_post_tilelang,
    mhc_fused_tilelang, mhc_pre_big_fuse_tilelang, hc_head_fuse_tilelang.
    FMA counts two operations; reductions count logical additions, while
    compiler padded/shuffle instructions are excluded. These are logical
    unique bytes, not observed DRAM or proof of cache residency. Global
    projection/sumsq partials are FP32; the BF16 shared intermediate inside
    the fused norm is not an additional global allocation.
    """
    if kernel.kind is not KernelKind.VECTOR or kernel.dtype != "bf16":
        raise ValueError("mHC stage work requires a BF16 vector source contract")
    if kernel.variant in ("mhc_prenorm", "mhc_prenorm_broadcast"):
        work = mhc_prenorm_roofline_work(kernel)
        logical = work["logical_work"]
        operands = logical["operands"]
        return {"stage": kernel.variant, "operands": operands, "demand": work["demand"],
                "read_bytes": sum(value["bytes"] for value in operands if value["access"] == "read"),
                "write_bytes": sum(value["bytes"] for value in operands if value["access"] == "write"),
                "semantic_fields": {"projection_partial_dtype": "fp32", "sqrsum_partial_dtype": "fp32",
                                    "projection_input": "BF16 global values converted to FP32", "global_fp32_input_copy": False},
                "views": [], "arithmetic_scope": work["arithmetic_contract"],
                "unpriced_typed_actions": {},
                "nonlinear_function_counts": {"sigmoid": 0, "exp": 0, "rsqrt": 0},
                "limitations": work["limitations"]}
    elements = kernel.shape["element_count"]
    h, m = kernel.shape["hidden"], kernel.shape["hc_mult"]
    if elements % (m * h):
        raise ValueError("mHC stage requires complete stream rows")
    t = elements // (m * h)
    mix = m * (m + 2)
    operands = []
    semantics, views = {}, []

    def tensor(role, dtype, shape, access):
        width = {"bf16": 2, "fp32": 4}[dtype]
        operands.append({"role": role, "dtype": dtype, "shape": shape,
                         "bytes": math.prod(shape) * width, "access": access})

    def post_operands():
        tensor("sublayer_output", "bf16", (t, h), "read")
        tensor("residual_input", "bf16", (t, m, h), "read")
        tensor("post_coefficients", "fp32", (t, m), "read")
        tensor("residual_coefficients", "fp32", (t, m, m), "read")
        tensor("residual_output", "bf16", (t, m, h), "write")

    fma, alu, sfu = 0, 0, 0
    typed_actions = {}
    nonlinear = {"sigmoid": 0, "exp": 0, "rsqrt": 0}
    if kernel.variant == "mhc_post":
        post_operands()
        fma = t * h * m * (2 * m + 1)
        semantics = {"post_mapping_accumulator_dtype": "fp32", "residual_output_dtype": "bf16",
                     "post_initial_multiply_dtype": "fp32", "post_initial_multiply_values": t * h * m}
    elif kernel.variant == "mhc_post_prenorm":
        post_operands()
        tiles = mix // kernel.shape["tile_n"]
        splits = kernel.shape["n_splits"]
        tensor("projection_weight", "fp32", (mix, m, h), "read")
        tensor("projection_partial", "fp32", (splits, t, mix), "write")
        tensor("sqrsum_partial", "fp32", (splits, t), "write")
        # Each projection tile recomputes the post mapping. Sumsq and
        # residual_out are emitted only by projection tile zero.
        fma = tiles * t * h * m * (2 * m + 1) + 2 * t * m * h * (mix + 1)
        semantics = {"projection_partial_dtype": "fp32", "sqrsum_partial_dtype": "fp32",
                     "residual_output_dtype": "bf16", "projection_uses_pre_store_fp32_residual": True,
                     "sqrsum_uses_pre_store_fp32_residual": True, "post_mapping_projection_tiles": tiles,
                     "post_initial_multiply_dtype": "fp32", "post_initial_multiply_values": tiles * t * h * m}
    elif kernel.variant in ("mhc_pre_norm", "mhc_pre_norm_broadcast"):
        splits, iters = kernel.shape["n_splits"], kernel.shape["sinkhorn_iters"]
        broadcast = kernel.variant == "mhc_pre_norm_broadcast"
        tensor("projection_partial", "fp32", (splits, t, mix), "read")
        tensor("sqrsum_partial", "fp32", (splits, t), "read")
        tensor("residual_input", "bf16", (t, h) if broadcast else (t, m, h), "read")
        tensor("norm_weight", "bf16", (h,), "read")
        tensor("hc_scale", "fp32", (3,), "read")
        tensor("hc_base", "fp32", (mix,), "read")
        tensor("post_coefficients", "fp32", (t, m), "write")
        tensor("residual_coefficients_flat", "fp32", (t, m * m), "write")
        tensor("layer_input", "bf16", (t, h), "write")
        if broadcast:
            tensor("residual_output", "bf16", (t, m, h), "write")
        fma = 2 * t * m * h + 2 * t * h
        # These split additions, scalar divides, eps additions, gate scale
        # operations and norm operations are FP32. The initial row maximum
        # is a comparison and retains its typed count without an INT32 rate.
        gate_ops = 6 * m + 2 * m * m
        sinkhorn_ops = (m * (m - 1) + m * m
                        + 2 * iters * m * (m - 1) + 4 * iters * m * m)
        alu = splits * t * (mix + 1) + t * mix + 2 * t * h
        # Both norm-weight kernels accumulate squares across hidden tiles
        # in gcd(1024,H) FP32 lanes, then reduce that fragment once per token
        # (tilelang_kernels.py:mhc_pre_big_fuse[_broadcast]_with_norm).
        # Existing 2*T*H terms cover square/accumulate and norm multiplication;
        # this addition is the final cross-position fragment reduction.
        alu += t * (math.gcd(1024, h) - 1)
        alu += t * (gate_ops + sinkhorn_ops + 4)
        maxima = t * m * (m - 1)
        fma += alu - maxima
        alu = 0
        typed_actions["sinkhorn_initial_row_max"] = {"dtype": "fp32", "operation": "maximum", "elements": maxima}
        nonlinear = {"sigmoid": 2 * t * m, "exp": t * m * m, "rsqrt": 2 * t}
        sfu = t * (2 * m + m * m + 2)
        semantics = {"projection_partial_dtype": "fp32", "sqrsum_partial_dtype": "fp32",
                     "post_coefficients_dtype": "fp32", "residual_coefficients_dtype": "fp32",
                     "layer_input_dtype": "bf16", "collapse_sumsq_before_shared_bf16_rounding": True,
                     "gamma_multiply_reads_shared_bf16": True, "shared_intermediate_is_global_allocation": False}
        views = [{"base_role": "post_coefficients", "shape": (t, m, 1), "operation": "unsqueeze" if broadcast else "view", "new_allocation": False},
                 {"base_role": "residual_coefficients_flat", "shape": (t, m, m), "operation": "view", "new_allocation": False}]
    elif kernel.variant == "hc_head":
        tensor("residual_input", "bf16", (t, m, h), "read")
        tensor("projection_weight", "fp32", (m, m * h), "read")
        tensor("hc_scale", "fp32", (1,), "read")
        tensor("hc_base", "fp32", (m,), "read")
        tensor("layer_input", "bf16", (t, h), "write")
        fma = 2 * t * m * m * h + 4 * t * m * h
        fma += t * (4 * m + 2)
        sfu = t * (m + 1)
        nonlinear = {"sigmoid": t * m, "exp": 0, "rsqrt": t}
        semantics = {"projection_and_gate_dtype": "fp32", "layer_input_dtype": "bf16",
                     "mixes_and_rsqrt_are_global_allocations": False, "residual_source_passes": 2}
    else:
        raise ValueError(f"unknown mHC stage: {kernel.variant!r}")
    return {"stage": kernel.variant, "operands": tuple(operands),
            "read_bytes": sum(value["bytes"] for value in operands if value["access"] == "read"),
            "write_bytes": sum(value["bytes"] for value in operands if value["access"] == "write"),
            "demand": {"compute_tensor": 0.0, "compute_fma": float(fma), "compute_reduction": 0.0,
                       "compute_alu": float(alu), "compute_sfu": float(sfu)},
            "semantic_fields": semantics, "views": views,
            "unpriced_typed_actions": typed_actions,
            "nonlinear_function_counts": nonlinear,
            "arithmetic_scope": "source logical MAC/scalar groups, excluding padded/shuffle instructions",
            "byte_scope": "unique global tensor roles; projection-tile/head-pass reloads and physical residency separate"}


def _mhc_model(kernel: KernelSpec, hardware):
    if kernel.variant in ("mhc_prenorm", "mhc_prenorm_broadcast"):
        raise NotImplementedError("mHC DeepGEMM prenorm launch is unbound")
    work = mhc_stage_logical_work(kernel)
    from src.kernel.memory_access_builder import elementwise_memory_access_program
    from src.kernel.memory_mhc import mhc_source_work
    source = mhc_source_work(elementwise_memory_access_program(kernel, hardware),
                             expected_kernel=kernel)
    total = float(source["read_bytes"] + source["write_bytes"])
    demand = build_forward_demand(total, total, True, work["demand"])
    inp = build_aggregate_gpu_input(
        kernel, hardware, demand,
        write_l2_bytes=float(source["write_bytes"]), write_dram_bytes=float(source["write_bytes"]),
        limitations=(
            "dsv4_mhc_roofline_only",
            "source_scalar_operation_counts_not_compiler_instruction_counts",
            "logical_unique_traffic_not_observed_dram",
            "projection_tile_and_head_pass_rereads_not_modeled",
            *(("final_rms_sumsq_fragment_logical_additions_counted_not_compiler_reduction_instructions",)
              if kernel.variant in ("mhc_pre_norm", "mhc_pre_norm_broadcast") else ()),
            "fp32_math_distinct_from_unpriced_max_and_nonlinear_compiler_services",
            "production_duration_calibration_not_used",
        ),
    )
    if kernel.variant == "mhc_post_prenorm":
        from src.kernel.memory_mhc import has_native_post_prenorm_geometry
        if not has_native_post_prenorm_geometry(kernel):
            inp = dataclasses.replace(inp, limitations=inp.limitations + (
                "mhc_source_tensor_abi_unbound_prior_numerical_support_retained",))
    return inp, total


def _int32_to_int64_materialization_model(kernel: KernelSpec, hardware):
    if kernel.launch is None:
        raise NotImplementedError("INT32-to-INT64 materialization launch is unbound")
    elements = kernel.shape["element_count"]
    read, write = float(4 * elements), float(8 * elements)
    dram_read = _resident_operand_dram_read_bytes(
        hardware, resident_footprint_bytes=read + write,
        read_bytes=read, compulsory_dram_read_bytes=0.0)
    dram_write = _completion_dependent_dram_write_bytes(
        hardware, resident_footprint_bytes=read + write, write_bytes=write)
    # Both retained programs issue one 32-bit sign extension per element:
    # sm80/sm90 SHF.R.S32.HI or MACA ASHR_I32. No float/SFU conversion or copy floor.
    demand = _vector_demand(
        hardware, l2_read_bytes=read, dram_read_bytes=dram_read,
        write_bytes=write, dram_write_bytes=dram_write,
        flops={"compute_tensor": 0.0, "compute_vector": 0.0,
               "compute_reduction": 0.0, "compute_fma": 0.0,
               "compute_sfu": 0.0, "compute_alu": float(elements)})
    inp = _input(kernel, hardware, demand, write_bytes=write,
                 dram_write_bytes=dram_write, phase_blueprint=None)
    source_limitations = {
        "pytorch_2_8_sm80_int32_to_int64": "installed_torch_2_8_sm80_static_cast_binding_not_historical_capture_identity",
        "pytorch_2_8_sm90_int32_to_int64": "installed_torch_2_8_sm90_static_cast_binding_not_historical_capture_identity",
        "pytorch_2_4_metax_3_7_2_int32_to_int64": "installed_torch_2_4_maca_generic_cast_binding_not_runtime_identity_or_enabled_optimized_cast",
        "pytorch_2_4_metax_3_7_2_int32_to_int64_optimized": "conditional_installed_maca_packed_integer_copy_not_observed_runtime_dispatch",
        "pytorch_2_4_metax_3_7_2_int32_to_int64_optimized_tail": "conditional_installed_maca_packed_integer_copy_with_scalar_tail_not_observed_runtime_dispatch",
    }
    return dataclasses.replace(inp, limitations=inp.limitations + (
        source_limitations[kernel.launch.algorithm],
        "integer_sign_extension_count_excludes_iterator_address_and_dispatch_instructions",
        "cache_traffic_uses_shared_residency_model_not_observed_hits",
    )), read + write


def _model(kernel: KernelSpec, hardware):
    if kernel.variant == "gather" and "materialization_source" in kernel.attributes:
        kernel.validate_materialization_launch(hardware)
    if kernel.variant == "vllm_attention_state_merge":
        raise NotImplementedError("attention state merge compiler, empty-state branches and launch are unbound")
    if kernel.variant == "vllm_plain_greedy_sample":
        if kernel.attributes["stage"] == "output_int32" and kernel.launch is not None:
            if hardware.supports_source_contract("pytorch_2_8_sm90_int64_int32_launch"):
                source_limit = "installed_sm90_long_to_int_source_not_actual_provider_validation"
                excluded_services = "address_dtype_dispatch_and_control_instruction_services_not_counted"
            elif hardware.supports_source_contract("pytorch_2_8_sm80_int64_int32_launch"):
                source_limit = "installed_sm80_long_to_int_source_not_actual_provider_validation"
                excluded_services = "address_dtype_dispatch_and_control_instruction_services_not_counted"
            elif hardware.supports_source_contract("pytorch_2_4_maca_small_int64_int32_launch"):
                source_limit = "installed_maca_small_long_to_int_source_not_actual_provider_validation"
                excluded_services = "address_dispatch_and_helper_call_instruction_services_not_counted"
            else:
                raise ValueError("greedy output cast requires its exact C500 small-iterator launch")
            elements = kernel.shape["element_count"]
            # The selected Long-input branch loads only the low32 bits at
            # 8B stride. cast_and_store<int> stores them unchanged; no data
            # conversion instruction or floating arithmetic is executed.
            # This holds in separately decoded MACA, SM80 and SM90 programs.
            read = write = float(4 * elements)
            demand = _vector_demand(hardware, l2_read_bytes=read, dram_read_bytes=read,
                write_bytes=write, flops={"compute_tensor": 0.0, "compute_fma": 0.0,
                    "compute_sfu": 0.0, "compute_alu": 0.0})
            inp = _input(kernel, hardware, demand, write_bytes=write, phase_blueprint=None)
            return dataclasses.replace(inp, limitations=inp.limitations + (
                source_limit,
                "compiled_lowword_load_bytes_not_observed_dram_transactions_or_cache_hits",
                excluded_services,
            )), float(12 * elements)
        raise NotImplementedError("plain greedy sampler library/compiler launch is unbound")
    if (kernel.variant == "vllm_embedding_id_widen"
            or kernel.variant == "elementwise" and kernel.attributes["operation"] == "cast_int32_int64"):
        return _int32_to_int64_materialization_model(kernel, hardware)
    if kernel.variant == "kimi_k3_situ":
        raise NotImplementedError("K3 SiTU tanhf compiler/local services remain unbound")
    if kernel.variant == "silu" and kernel.attributes["swiglu_limit"] is not None:
        work = clamped_silu_logical_work(kernel)
        from src.kernel.memory_access_builder import scalar_prediction_work
        source = scalar_prediction_work(kernel, hardware)
        read, write = float(source["read_bytes"]), float(source["write_bytes"])
        total = read + write
        demand = build_forward_demand(total, total, True, {
            "compute_tensor": 0.0, **work["baseline_demand"]})
        return build_aggregate_gpu_input(kernel, hardware, demand,
            write_l2_bytes=write, write_dram_bytes=write,
            limitations=("clamped_silu_roofline_only",
                         "logical_clamp_and_silu_math_not_compiler_instructions",
                         "typed_negation_float_minmax_conversion_and_division_lowering_services_unpriced",
                         "actual_clamped_activation_launch_and_local_services_unbound")), total
    kernel = _gpu_full_graph_source_program_execution_kernel(
        kernel, hardware)
    kernel = _metax_full_graph_norm_execution_kernel(kernel, hardware)
    kernel = _cann_full_graph_source_program_execution_kernel(
        kernel, hardware)
    if kernel.variant == "dsv4_short_context_topk":
        from src.kernel.memory_access_builder import elementwise_memory_access_program
        from src.kernel.memory_path_solver import short_context_topk_source_demands
        source = short_context_topk_source_demands(elementwise_memory_access_program(kernel,hardware),expected_kernel=kernel)
        rows,capacity = source["geometry"]
        read,write = float(source["read_bytes"]),float(source["write_bytes"])
        # One logical position add/divide per row, comparison and select
        # per written entry. Integer addressing/compiler padding unpriced.
        demand = build_forward_demand(read + write, read + write, True, {
            "compute_tensor": 0.0, "compute_fma": 0.0,
            "compute_alu": float(2 * rows + 2 * rows * capacity), "compute_sfu": 0.0})
        return build_aggregate_gpu_input(kernel, hardware, demand,
            write_l2_bytes=write, write_dram_bytes=write,
            limitations=("dsv4_short_context_fill_roofline_only",
                         "logical_unique_position_read_and_full_topk_write_not_observed_dram",
                         "logical_integer_work_not_compiler_instruction_count",
                         "explicit_eager_dict_all_valid_source_scenario_not_runtime_observation")), read + write
    if kernel.variant == "dsv4_moe_route":
        if kernel.attributes["routing_source"] == "vllm_0_30_cuda_hash_top6_pure_text":
            return _dsv4_hash_route_model(kernel, hardware)
        return _dsv4_triton_route_model(kernel, hardware)
    if kernel.variant == "vllm_logits_row_select":
        if kernel.launch is None:
            raise NotImplementedError("target logits row selection library/compiler launch is unbound")
        elements = kernel.shape["element_count"]
        if hardware.supports_source_contract("pytorch_2_4_maca_scalar_index_launch"):
            # index_elementwise_kernel_1_1 loads one Long ID for each active
            # scalar copy, after the tail predicate. No BF16 arithmetic or
            # conversion occurs; index address/control work is excluded.
            read, write = float(10 * elements), float(2 * elements)
            demand = _vector_demand(hardware, l2_read_bytes=read, dram_read_bytes=read,
                write_bytes=write, flops={"compute_tensor": 0.0, "compute_fma": 0.0,
                    "compute_sfu": 0.0, "compute_alu": 0.0})
            inp = _input(kernel, hardware, demand, write_bytes=write, phase_blueprint=None)
            return dataclasses.replace(inp, limitations=inp.limitations + (
                "installed_torch_2_4_maca_scalar_indexing_not_runtime_validation",
                "active_scalar_index_loads_no_inferred_broadcast_cache_credit",
                "address_and_uniform_control_instruction_services_not_counted",
            )), float(4 * elements + 8 * kernel.shape["rows"])
        # vectorized_gather loads an ID in every launched thread before its
        # 16B-payload tail predicate, including threads in the partial tile.
        read = float(2 * elements + 8 * kernel.launch.grid_size * kernel.launch.block_size)
        write = float(2 * elements)
        demand = _vector_demand(hardware, l2_read_bytes=read, dram_read_bytes=read,
            write_bytes=write, flops={"compute_tensor": 0.0, "compute_fma": 0.0,
                                     "compute_sfu": 0.0, "compute_alu": float(elements)})
        inp = _input(kernel, hardware, demand, write_bytes=write, phase_blueprint=None)
        return dataclasses.replace(inp, limitations=inp.limitations + (
            "installed_torch_2_8_cuda_vectorized_indexing_static_source_not_runtime_validation",
            "thread_index_loads_counted_before_tail_without_inferred_broadcast_cache_credit",
            "address_and_uniform_control_instruction_services_not_counted",
        )), float(4 * elements + 8 * kernel.shape["rows"])
    if kernel.variant == "vllm_logits_gather_reorder":
        raise NotImplementedError("logits gather reorder library/compiler launch is unbound")
    if kernel.variant == "vllm_logits_fp32_cast":
        if kernel.launch is not None:
            if hardware.supports_source_contract("pytorch_2_8_sm80_logits_cast_launch"):
                if hardware.nominal_sm_freq_hz != 1_140_000_000:
                    raise NotImplementedError("A800 PRMT SI service is measured only at1140MHz")
                elements = kernel.shape["element_count"]
                read, write = float(2 * elements), float(4 * elements)
                # Installed SM80 BF16 path is PRMT(RZ,0x5410,bits), not SHF,
                # F2F or floating arithmetic. Use its independent named lane
                # issue service, conserving one operation per output value.
                demand = _vector_demand(hardware, l2_read_bytes=read, dram_read_bytes=read,
                    write_bytes=write, flops={"compute_tensor": 0.0, "compute_fma": 0.0,
                        "compute_sfu": 0.0, "compute_alu": float(elements)})
                inp = _input(kernel, hardware, demand, write_bytes=write, phase_blueprint=None)
                inp = _replace_compute_service_demands(inp, "compute_alu",
                    (ComputeServiceDemand("prmt_b32_bf16_expand", float(elements)),))
                return dataclasses.replace(inp, limitations=inp.limitations + (
                    "installed_sm80_copy_with_independent_exact_prmt_lane_service_not_actual_provider",
                    "prmt_dependency_probe_reaches_zero_after_two_steps_rotation_control_agrees",
                    "sustained_register_service_includes_bounded_loop_timer_and_scheduling_overhead",
                    "fixed_1140MHz_service_not_extrapolated_to_other_clocks",
                    "address_dtype_dispatch_and_uniform_control_services_not_counted",
                )), read + write
            if not (hardware.supports_source_contract("pytorch_2_8_sm90_logits_cast_launch")
                    or hardware.supports_source_contract("pytorch_2_4_maca_logits_cast_launch")):
                raise ValueError("target logits cast requires a declared source launch capability")
            elements = kernel.shape["element_count"]
            read, write = float(2 * elements), float(4 * elements)
            # A packed BF16x4 becomes FP32x4 with two SHL_B32 and two
            # AND_B32; scalar tail elements each use one SHL_B32. These
            # bit expansions use existing integer issue, never F2F or SFU.
            # The generic BF16 input branch uses one SHL_B32 per value;
            # cast_and_store<float> writes those bits without conversion.
            # The independently decoded SM90 entry instead uses one
            # IMAD.U32(value,65536,0) per value on the ordinary INT32 ALU.
            demand = _vector_demand(hardware, l2_read_bytes=read, dram_read_bytes=read,
                write_bytes=write, flops={"compute_tensor": 0.0, "compute_fma": 0.0,
                    "compute_sfu": 0.0, "compute_alu": float(elements)})
            inp = _input(kernel, hardware, demand, write_bytes=write, phase_blueprint=None)
            return dataclasses.replace(inp, limitations=inp.limitations + (
                "source_bound_gpu_copy_program_not_observed_runtime_dispatch",
                "bf16_bit_expansion_uses_integer_alu_not_floating_conversion",
                "address_uniform_and_tail_index_helper_instruction_services_not_counted",
            )), read + write
        raise NotImplementedError("target logits cast library/compiler launch is unbound")
    if kernel.variant == "vllm_rejection_logits_materialize":
        raise NotImplementedError("rejection materialization library/compiler launch is unbound")
    if kernel.variant in (
            "dsv32_draft_argmax", "dsv32_draft_id_cast", "dsv32_draft_row_select", "dsv32_draft_buffer_copy", "dsv32_draft_token_stack", "dsv32_draft_id_scatter", "dsv32_draft_prepare_next_ids", "dsv32_draft_prepare_sample_indices", "dsv32_draft_seq_rollback", "dsv32_draft_step_metadata"):
        raise NotImplementedError("draft sampling library/compiler launch is unbound")
    if kernel.variant == "vocab_parallel_embedding":
        raise NotImplementedError("vocab embedding token ownership and pointer alignment are unbound")
    if kernel.variant.startswith("moe_"):
        return _moe_aux_model(kernel, hardware)
    elif kernel.variant == "dsv4_q_kv_rmsnorm":
        return _dsv4_q_kv_rmsnorm_model(kernel, hardware)
    elif kernel.variant in ("dsv32_fused_norm_rope", "dsv32_fused_q"):
        return _dsv32_target_fusion_model(kernel, hardware)
    elif kernel.variant == "dsv32_embed_norm":
        return _dsv32_embed_norm_model(kernel, hardware)
    elif kernel.variant in ("dsv32_eh_norm", "dsv32_embed_eh_norm"):
        return _dsv32_eh_norm_model(kernel, hardware)
    elif kernel.variant in (
            "mhc_prenorm", "mhc_prenorm_broadcast", "mhc_post_prenorm",
            "mhc_pre_norm", "mhc_pre_norm_broadcast", "mhc_post", "hc_head"):
        return _mhc_model(kernel, hardware)
    elif kernel.variant in {
        "rmsnorm", "add_rmsnorm", "layernorm", "mla_rope", "elementwise",
        "elementwise_pytorch_vec4", "rotary", "rope",
        "dsv4_inv_rope_fp8_quant",
        "qkv_rmsnorm_rope",
        "activation", "silu",
        "reduce", "gather", "softmax",
        "gemm_reduce", "gemm_elementwise", "flash_mla_metadata", "fa3_prepare_varlen",
        "fp8_group_quant",
    }:
        return _regular_model(kernel, hardware)
    else:
        raise ValueError(f"unknown VECTOR variant: {kernel.variant!r}")


def paged_kv_cache_resource_input(kernel: KernelSpec, hardware):
    """Reuse the established paged-cache physical model under its own kind."""

    if ("mathematical_program" in kernel.attributes
            and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
        raise NotImplementedError("dense FP16 mathematical work has no native launch")
    if (kernel.kind is not KernelKind.KV_CACHE
            or kernel.variant != "paged_kv_cache"):
        raise ValueError(
            "paged KV cache resource input requires "
            "KV_CACHE/paged_kv_cache")
    return _regular_model(kernel, hardware)


def forward_analytical_resource_input(kernel: KernelSpec, hardware):
    """Build Forward's final CANN analytical envelope.

    The public resource-input route intentionally keeps the source-DAG form
    available for contract validation.  This helper evaluates the same static
    workload with the production Forward representation: phase ledger,
    physical services, analytical dependency envelope, and launch floor.
    """

    if ("mathematical_program" in kernel.attributes
            and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
        raise NotImplementedError("dense FP16 mathematical work has no native launch")
    token = _FORWARD_CANN_ANALYTICAL_ENVELOPE.set(True)
    try:
        if (kernel.kind is KernelKind.KV_CACHE
                and kernel.variant == "paged_kv_cache"):
            return _regular_model(kernel, hardware)
        return _model(kernel, hardware)
    finally:
        _FORWARD_CANN_ANALYTICAL_ENVELOPE.reset(token)


def bw1100_vector_memory_only_bytes(kernel: KernelSpec):
    """Explicit ideal logical-payload approximation, excluding vector compute.

    This is not a proof that an operator is memory bound. In particular the
    whole mHC wrapper uses public operands and parameters, with no invented
    split scratch or compiler materialization. Unknown variants still reject.
    """
    if kernel.kind is not KernelKind.VECTOR or not HWSpec.source_contract_supported("aggregate_gpu_source_roofline", kernel.hardware_id):
        raise ValueError("BW1100 vector memory approximation requires its VECTOR contract")
    variant = kernel.variant
    packed_weights = "packed_weight_storage" in kernel.attributes
    operand_ledgers = {
        "silu": clamped_silu_logical_work,
        "rmsnorm": rmsnorm_logical_work,
        "dsv4_indexer_q_rope_quant": dsv4_indexer_q_rope_quant_logical_work,
        "dsv4_moe_route": dsv4_moe_route_logical_work,
        "vllm_plain_greedy_sample": vllm_plain_greedy_sampling_logical_work,
        "vllm_embedding_id_widen": vllm_embedding_id_widen_logical_work,
        "vllm_logits_fp32_cast": vllm_logits_fp32_cast_logical_work,
        "vllm_logits_gather_reorder": vllm_logits_gather_reorder_logical_work,
    }
    if variant in operand_ledgers:
        return sum(value["bytes"] for value in operand_ledgers[variant](kernel)["operands"])
    if variant == "vocab_parallel_embedding":
        work = vocab_parallel_embedding_logical_work(kernel)
        if work["owned_token_rows"] is None:
            raise NotImplementedError("BW1100 embedding ownership remains unbound")
        total = sum(value["bytes"] for value in work["operands"])
        if packed_weights:
            weight = next(value for value in work["operands"] if value["role"] == "owned_weight_rows")
            total += weight["elements"] // 2 + weight["elements"] // 32 - weight["bytes"]
        return total
    if variant == "vllm_logits_row_select":
        return vllm_logits_row_selection_roofline_bytes(kernel)
    if variant in ("dsv4_q_kv_rmsnorm", "dsv4_inv_rope_fp8_quant"):
        work = (dsv4_qkv_rmsnorm_logical_work(kernel) if variant == "dsv4_q_kv_rmsnorm"
                else dsv4_inverse_rope_quant_logical_work(kernel))
        return work["read_bytes"] + work["write_bytes"]
    if variant in ("mhc_pre", "mhc_post_pre"):
        if kernel.attributes["mathematical_program"] != "vllm_mhc_wrapper_math_v1":
            raise NotImplementedError("BW1100 mHC requires its explicit mathematical wrapper")
        h, c = kernel.shape["hidden"], kernel.shape["hc_mult"]
        rows = kernel.shape["element_count"] // (h * c)
        mixes = c * (c + 2)
        # Public parameter roles: FP32 projection, scale[3], base[mixes],
        # BF16 RMSNorm gamma[H]. Broadcast pre uses fn_broadcast[mixes,H].
        projection_width = h if variant == "mhc_pre" else c * h
        parameter_bytes = 4 * mixes * projection_width + 4 * (3 + mixes) + 2 * h
        if packed_weights:
            weights = mixes * projection_width
            parameter_bytes += weights // 2 + weights // 32 - 4 * weights
        input_bytes = 2 * rows * h
        if variant == "mhc_post_pre":
            input_bytes += 2 * rows * c * h + 4 * rows * (c + c * c)
        output_bytes = 2 * rows * (c * h + h) + 4 * rows * (c + c * c)
        return parameter_bytes + input_bytes + output_bytes
    if variant in ("mhc_post", "hc_head", "mhc_prenorm", "mhc_prenorm_broadcast",
            "mhc_post_prenorm", "mhc_pre_norm", "mhc_pre_norm_broadcast"):
        work = mhc_stage_logical_work(kernel)
        total = work["read_bytes"] + work["write_bytes"]
        if packed_weights:
            weight = next(value for value in work["operands"] if value["role"] == "projection_weight")
            weights = math.prod(weight["shape"])
            total += weights // 2 + weights // 32 - weight["bytes"]
        return total
    elements, width = kernel.shape["element_count"], kernel.shape["dtype_bytes"]
    if variant == "gather":
        read_bytes = elements * width * kernel.attributes["gather_factor"]
        if packed_weights:
            weights = elements * kernel.attributes["gather_factor"]
            read_bytes = weights // 2 + weights // 32
        read_bytes += kernel.attributes["index_count"] * kernel.attributes["index_bytes"]
        return read_bytes + (elements * width if kernel.attributes["materialized_output"] else 0)
    if variant == "fp8_group_quant":
        if kernel.attributes["source_program"] is not None:
            return fp8_group_quant_source_work(kernel)["logical_bytes"]
        group = kernel.attributes["group_size"]
        if elements % group:
            raise ValueError("FP8 logical payload requires complete quantization groups")
        return elements * width + elements + 4 * (elements // group)
    if variant == "elementwise":
        operation = kernel.attributes["operation"]
        if operation not in ("add", "mul", "copy"):
            raise NotImplementedError(f"BW1100 memory approximation has no {operation} operand ledger")
        return elements * width * (2 if operation == "copy" else 3)
    if variant == "reduce":
        # Explicit source projection: all input contributions are read,
        # one same-width output is written for each logical output element.
        return elements * width * (kernel.attributes["reduction_factor"] + 1)
    if variant == "moe_sum":
        rows, hidden, topk = (kernel.shape[key] for key in ("tokens", "hidden", "topk"))
        total = rows * hidden * (topk + 1) * width
        # Heterogeneous merge additionally consumes the public FP32 weights.
        if kernel.attributes["routed_weights_dtype"] == "fp32":
            total += 4 * rows * topk
        return total * kernel.attributes["work_fraction"]
    if variant == "dsv4_short_context_topk":
        work = dsv4_short_context_topk_source_work(kernel)
        return work["positions"]["read_bytes"] + work["output"]["write_bytes"]
    raise NotImplementedError(f"BW1100 memory approximation has no source byte ledger for {variant}")


def _cann_transpose_alias_prediction(kernel,hardware,method):
    from src.kernel.memory_access_builder import elementwise_memory_access_program
    from src.kernel.memory_cann_moe_routing import cann_moe_transpose_source_demands
    work=cann_moe_transpose_source_demands(elementwise_memory_access_program(kernel,hardware))
    if work['read_bytes']!=0 or work['write_bytes']!=0:raise ValueError('Transpose alias cannot price a materialized copy')
    return prediction_from_ns(0.0,method)


class VectorPredictor(KernelPredictor):
    kind = KernelKind.VECTOR

    def __init__(self):
        self._cached_forward_kernel = None
        self._cached_forward_hardware = None
        self._cached_forward_value = None

    def analytical_without_launch(self, kernel: KernelSpec, hardware):
        """Performance-only models do not execute or inspect tensor values."""
        if kernel.variant == "projected_attention_path":
            from src.kernel.predictors.projected_attention import source_prediction
            return source_prediction(kernel, hardware)
        if ("source_component" in kernel.attributes
                and kernel.attributes["source_component"] == "vllm_0_30_kimi_k3_triton_chunk"):
            inp, _ = kimi_k3_kda_chunk_stage_source_input(kernel, hardware)
            prediction = PerformanceFormula(hardware).predict_kernel(inp)
            return dataclasses.replace(prediction, bottleneck_group="analytical_kda_chunk_source_pipeline")

        if (kernel.variant == "elementwise" and "mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] == "vllm_0_30_fa3_aot_tail_clear"):
            return self.roofline_without_launch(kernel, hardware)
        if kernel.variant == "dsv32_draft_argmax":
            work = dsv32_draft_sampling_logical_work(kernel)
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            seconds = logical_bytes / hardware.resource_by_role("dram").capacity
            return prediction_from_ns(seconds * 1e9, "analytical_sampler_memory")
        if kernel.variant == "vllm_plain_greedy_sample":
            rows = kernel.shape["rows"]
            if kernel.attributes["stage"] == "argmax":
                # One scan of FP32 logits and one INT64 index per row.
                logical_bytes = 4 * rows * kernel.shape["vocab"] + 8 * rows
            elif kernel.attributes["stage"] == "output_int32":
                logical_bytes = 12 * rows
            else:
                raise AssertionError("unhandled analytical sampling stage")
            seconds = logical_bytes / hardware.resource_by_role("dram").capacity
            return prediction_from_ns(seconds * 1e9, "analytical_sampler_memory")
        if kernel.variant in (
                "vllm_embedding_id_widen", "vllm_logits_fp32_cast",
                "vllm_logits_row_select", "vllm_masked_embedding"):
            prediction = self.roofline_without_launch(kernel, hardware)
            return dataclasses.replace(prediction, bottleneck_group="analytical_materialization")
        if kernel.variant == "gather" and "index_select_source" not in kernel.attributes:
            elements = kernel.shape["element_count"]
            payload = elements * kernel.shape["dtype_bytes"]
            logical_bytes = payload * kernel.attributes["gather_factor"]
            logical_bytes += kernel.attributes["index_count"] * kernel.attributes["index_bytes"]
            if kernel.attributes["materialized_output"]:
                logical_bytes += payload
            seconds = logical_bytes / hardware.resource_by_role("dram").capacity
            return prediction_from_ns(seconds * 1e9, "analytical_materialization")
        if ((kernel.variant == "gather" and "index_select_source" in kernel.attributes)
                or (kernel.variant == "elementwise" and kernel.attributes["operation"] == "cast_int32_int64"
                    and kernel.attributes["tensor_iterator_source"] == "aten_advanced_indexing_long")):
            prediction = self.roofline_without_launch(kernel, hardware)
            return dataclasses.replace(prediction, bottleneck_group="analytical_materialization")
        # Reuse the owner's explicit mathematical programs, including routing
        # and TP materialization. Unknown programs still raise in that closed
        # dispatch; native launch availability is a separate contract.
        prediction = self.roofline_without_launch(kernel, hardware)
        return dataclasses.replace(prediction, bottleneck_group="analytical_logical_work")

    def resource_input(self, kernel: KernelSpec, hardware):
        if ("source_component" in kernel.attributes
                and kernel.attributes["source_component"] == "vllm_0_30_kimi_k3_triton_chunk"):
            return kimi_k3_kda_chunk_stage_source_input(kernel, hardware)

        if HWSpec.source_contract_supported("programmed_mxfp4_fp8_expert_service", hardware.hardware_id):
            raise NotImplementedError("FPGA vector element service has no native resource-input program")
        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
            raise NotImplementedError("dense FP16 mathematical work has no native launch")
        if (kernel.variant == "dsv32_fused_norm_rope"
                and kernel.attributes["cache_slot_scope"] == "no_metadata_no_cache_slots"):
            raise NotImplementedError("metadata=None fusion has no native source-memory/launch program")
        if kernel.variant == "vllm_mtp_eager":
            raise NotImplementedError("MTP eager source compiler/library services are unbound")
        if kernel.variant == "vllm_mtp_position_mask":
            raise NotImplementedError("MTP mask indexing/compiler/launch services are unbound")
        if kernel.variant == "vllm_masked_embedding":
            raise NotImplementedError("masked embedding native integer/selection/compiler services are unbound")
        if kernel.variant == "moe_topk" and "source_program" in kernel.attributes:
            raise NotImplementedError("source softmax/top-k selection and reduction service is unbound; legacy top-k accounting cannot substitute")
        if kernel.variant == "fp8_group_quant" and kernel.attributes["source_program"] is not None:
            raise NotImplementedError("conditional FP8 source has no single native resource-input program")
        from src.kernel.memory_cann_normalization import has_cann_normalization_source, cann_normalization_source_work, cann_normalization_source_demands
        if has_cann_normalization_source(kernel,hardware):
            from src.kernel.memory_access_builder import normalization_memory_access_program, memory_execution_kernel
            execution = memory_execution_kernel(kernel,hardware)
            work = cann_normalization_source_demands(normalization_memory_access_program(execution,hardware))
            with cann_normalization_source_work(execution,work):
                return _model(kernel,hardware)
        inp, compulsory = _model(kernel, hardware)
        return _attach_moe_align_shared_atomic_floor(inp, kernel, hardware), compulsory

    def roofline_without_launch(self, kernel: KernelSpec, hardware):
        if kernel.variant == "projected_attention_path":
            from src.kernel.predictors.projected_attention import source_prediction
            return source_prediction(kernel, hardware)
        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] == "vllm_0_30_dspark_typed_role_bytes_v1"):
            if (kernel.hardware_id != hardware.hardware_id
                    or not hardware.supports_source_contract("vllm_0_30_symbolic_mhc")
                    or kernel.variant != "elementwise" or kernel.launch is not None
                    or kernel.execution_support != "unsupported"
                    or kernel.attributes["operation"] not in ("read", "fill")):
                raise ValueError("DSpark typed payload requires its exact unbound source contract")
            # Current source typed role bytes only. A write projection does
            # not set state values; comparisons/addressing/issue remain partial.
            logical_bytes = (kernel.shape["element_count"] * kernel.shape["dtype_bytes"]
                * (kernel.attributes["reads"] + kernel.attributes["writes"]))
            return prediction_from_ns(logical_bytes / hardware.resource_by_role("dram").capacity * 1e9,
                "analytical_dspark_typed_payload")
        if ("source_component" in kernel.attributes
                and kernel.attributes["source_component"] == "vllm_0_30_kimi_k3_triton_chunk"):
            raise NotImplementedError("KDA chunk child has no whole-parent roofline fallback")

        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] == "vllm_0_30_fa3_aot_tail_clear"):
            if (kernel.hardware_id != hardware.hardware_id
                    or not hardware.supports_source_contract("vllm_0_30_fa3_gqa_fresh_prefill")
                    or kernel.variant != "elementwise" or kernel.dtype != "int32"
                    or kernel.execution_support != "unsupported" or kernel.launch is not None
                    or kernel.attributes["operation"] != "fill"
                    or kernel.attributes["reads"] != 0 or kernel.attributes["writes"] != 1):
                raise ValueError("FA3 AOT tail clear requires its unbound H200 INT32 source contract")
            # Actual output payload only. Native compiler/launch/startup are
            # unbound; no synthetic grid or new per-program rate is supplied.
            output_bytes = kernel.shape["element_count"] * kernel.shape["dtype_bytes"]
            write_capacity = hardware.dram_capacity_for_access("write",
                active_units=hardware.num_compute_units,
                sm_freq_hz=hardware.nominal_sm_freq_hz,
                dram_freq_hz=hardware.nominal_dram_freq_hz)
            return prediction_from_ns(output_bytes / write_capacity * 1e9,
                "analytical_fa3_metadata_clear")
        if (kernel.variant == "silu" and kernel.attributes["swiglu_limit"] is not None
                and hardware.supports_source_contract("unbound_clamped_silu_source_math")):
            work = clamped_silu_logical_work(kernel)
            demand = {role: 0 for role in ("compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            demand.update(work["baseline_demand"])
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            from src.kernel.memory_access_builder import has_mathematical_memory_source, mathematical_prediction_memory_bytes
            if has_mathematical_memory_source(kernel):
                logical_bytes = mathematical_prediction_memory_bytes(kernel, hardware)
            return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")
        if (kernel.variant == "gather" and "index_select_source" not in kernel.attributes
                and "mathematical_program" not in kernel.attributes
                and hardware.supports_source_contract("unbound_materialized_gather_source_math")):
            return self.analytical_without_launch(kernel, hardware)
        if HWSpec.source_contract_supported("aten_advanced_indexing_long_math", hardware.hardware_id) and (
                (HWSpec.source_contract_supported("vllm_0_11_embedding_index_select_math", hardware.hardware_id) and kernel.variant == "gather" and "index_select_source" in kernel.attributes
                    and kernel.attributes["index_select_source"] == "vllm_0_11_embedding")
                or (kernel.variant == "elementwise" and kernel.attributes["operation"] == "cast_int32_int64"
                    and kernel.attributes["tensor_iterator_source"] == "aten_advanced_indexing_long")):
            physical = (kernel.attributes["model_input_shape"]
                if "model_input_shape" in kernel.attributes else kernel.shape)
            if kernel.variant == "gather":
                # F.embedding: selected BF16 rows, fresh BF16 output, Long IDs.
                logical_bytes = 2 * physical["element_count"] * kernel.shape["dtype_bytes"] + 8 * physical["rows"]
            else:
                # Int input plus independently allocated Long indices; no
                # floating-point work or compiler instruction count inferred.
                logical_bytes = (4 + 8) * physical["element_count"]
            demand = {role: 0.0 for role in (
                "compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")
        if (HWSpec.source_contract_supported("vllm_0_30_v32_target_fusion_math", hardware.hardware_id)
                and kernel.variant in ("dsv32_fused_norm_rope", "dsv32_fused_q")):
            work = dsv32_target_fusion_logical_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if HWSpec.source_contract_supported("aggregate_gpu_source_roofline", hardware.hardware_id):
            if hardware.gpu_vector_memory_only:
                logical_bytes = bw1100_vector_memory_only_bytes(kernel)
                return prediction_from_ns(logical_bytes / hardware.resource_by_role("dram").capacity * 1e9,
                    "roofline_gpu_vector_memory_only")
            if kernel.variant == "vllm_logits_fp32_cast":
                work = vllm_logits_fp32_cast_logical_work(kernel)
                logical_bytes = sum(operand["bytes"] for operand in work["operands"])
                return prediction_from_ns(roofline_ns(work["demand"], hardware, logical_bytes), "roofline")
            if kernel.variant == "vllm_logits_row_select":
                logical_bytes = vllm_logits_row_selection_roofline_bytes(kernel)
                return prediction_from_ns(logical_bytes / hardware.resource_by_role("dram").capacity * 1e9, "roofline")
            if not (kernel.variant == "gather" and "mathematical_program" in kernel.attributes):
                raise NotImplementedError(f"BW1100 {kernel.variant}: ordinary FP32/vector/SFU/typed-action service binding is unavailable; matrix peak cannot substitute")
        if HWSpec.source_contract_supported("programmed_mxfp4_fp8_expert_service", hardware.hardware_id):
            # User-declared whole-vector-operation service, not a collection
            # of independently concurrent FMA/SFU pipes. This initial binding
            # covers standalone BF16 HBM programs; compiler fusion/on-chip
            # residency and the rest of the routed expert chain stay unbound.
            if kernel.dtype != "bf16" or kernel.variant not in ("silu", "rmsnorm", "softmax", "fp8_group_quant", "gather"):
                raise NotImplementedError("FPGA vector operation has no standalone logical-byte binding")
            elements = kernel.shape["element_count"]
            if kernel.variant == "gather":
                if kernel.attributes["index_count"] != 0 or not kernel.attributes["materialized_output"]:
                    raise NotImplementedError("FPGA copy binds only explicit unindexed materialization")
                logical_bytes = 4 * elements
            elif kernel.variant == "fp8_group_quant":
                if kernel.attributes["group_size"] != 128:
                    raise NotImplementedError("FPGA quantizer binds only group128 FP32 scales")
                logical_bytes = elements + 4 * elements // 128
                if kernel.attributes["input_resource"] == "dram":
                    logical_bytes += 2 * elements
            elif kernel.variant == "silu":
                logical_bytes = 6 * elements  # gate, up and fresh product
            elif kernel.variant == "softmax":
                logical_bytes = 4 * elements  # input and fresh output
            else:
                if ("hidden" not in kernel.shape or "rows" not in kernel.shape
                        or elements != kernel.shape["hidden"] * kernel.shape["rows"]):
                    raise ValueError("FPGA RMSNorm requires complete rows/hidden geometry")
                logical_bytes = 4 * elements + 2 * kernel.shape["hidden"]
            execution = hardware.fpga_execution
            cycles = math.ceil(elements / execution["vector_elements_per_cycle"])
            peak = execution["clock_hz"] * execution["vector_elements_per_cycle"]
            utilization = hardware.resource_by_role("compute_vector").capacity / peak
            seconds = max(cycles / execution["clock_hz"] / utilization,
                logical_bytes / hardware.resource_by_role("dram").capacity)
            seconds += execution["vector_latency_cycles"] / execution["clock_hz"]
            seconds += execution["hbm_latency_ns"] / 1e9
            return prediction_from_ns(seconds * 1e9, "fpga_vector")
        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
            work = {"fp16": dense_fp16_source_logical_work, "bf16": dense_bf16_source_logical_work}[kernel.dtype](kernel)
            from src.kernel.memory_access_builder import has_mathematical_memory_source, mathematical_prediction_memory_bytes
            if has_mathematical_memory_source(kernel):
                work = {**work, "logical_bytes": mathematical_prediction_memory_bytes(kernel, hardware)}
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "gather" and "mathematical_program" in kernel.attributes:
            # Explicit typed copy: each FP32 element is read and written once.
            # Logical operand bytes do not bind issued traffic or a provider.
            demand = {role: 0 for role in ("compute_tensor", "compute_vector", "compute_reduction",
                "compute_fma", "compute_sfu", "compute_alu")}
            logical_bytes = 2 * kernel.shape["element_count"] * kernel.shape["dtype_bytes"]
            if kernel.attributes["mathematical_program"] == "materialized_bf16_gather_bytes_v1":
                logical_bytes += kernel.attributes["index_count"] * kernel.attributes["index_bytes"]
            return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")
        if kernel.variant == "vllm_attention_state_merge":
            work = attention_state_merge_roofline_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant in ("dsv32_moe_route", "kimi_moe_route"):
            if kernel.attributes["mathematical_program"] is None:
                raise NotImplementedError(f"VECTOR/{kernel.variant} requires an explicit mathematical routing program; complete source selection services remain unbound")
            work = biased_sigmoid_topk_roofline_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "vllm_mtp_eager":
            work = vllm_mtp_eager_roofline_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "vllm_mtp_position_mask":
            rows, width = kernel.shape["rows"], kernel.shape["hidden"]
            # Compare materializes bool[rows]; index assignment reads that
            # predicate and writes only the selected BF16 embedding rows.
            # Internal nonzero/indexing scratch and launch are unbound.
            if kernel.attributes["stage"] == "compare":
                logical_bytes = 9 * rows
            elif kernel.attributes["stage"] == "fill":
                logical_bytes = rows + 2 * width * kernel.attributes["masked_rows"]
            elif kernel.attributes["stage"] == "where":
                #0.27 torch.where has a full BF16 operand and a fresh full
                # output. Public-role bytes do not bind compiler loads or
                # assume masked source rows are skipped by the provider.
                logical_bytes = rows + 4 * rows * width
            else:
                raise AssertionError("unhandled MTP position-mask source stage")
            demand = {role: 0.0 for role in (
                "compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")
        if kernel.variant == "vllm_masked_embedding":
            work = vllm_masked_embedding_logical_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "moe_topk" and "source_program" in kernel.attributes:
            if "mathematical_program" in kernel.attributes:
                source_program = kernel.attributes["source_program"]
                if source_program == "vllm_0_11_fp32_sigmoid_bias_topk":
                    work = sigmoid_bias_topk_roofline_work(kernel)
                elif source_program in ("vllm_0_30_bf16_softmax_topk", "vllm_0_18_bf16_softmax_topk", "vllm_0_24_bf16_softmax_topk", "vllm_0_11_fp32_softmax_topk"):
                    work = softmax_topk_roofline_work(kernel)
                elif source_program in ("vllm_0_11_bf16_sigmoid_bias_grouped_topk", "vllm_0_27_1_bf16_sigmoid_bias_grouped_topk", "sglang_0_5_19_fp32_sigmoid_bias_grouped_topk"):
                    work = grouped_sigmoid_bias_topk_roofline_work(kernel)
                else:
                    raise AssertionError("unhandled source top-k mathematical program")
                from src.kernel.memory_access_builder import has_mathematical_memory_source, mathematical_prediction_memory_bytes
                if has_mathematical_memory_source(kernel):
                    work = {**work, "logical_bytes": mathematical_prediction_memory_bytes(kernel, hardware)}
                return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
            raise NotImplementedError("source softmax/top-k selection and reduction service is unbound; legacy top-k accounting cannot substitute")
        if (kernel.variant in ("moe_init_routing", "moe_abs", "moe_token_unpermute")
                and "mathematical_program" in kernel.attributes):
            work = ascend018_moe_dispatch_roofline_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        int32_operations = 0
        if kernel.variant == "fp8_group_quant" and kernel.attributes["source_program"] is not None:
            work = fp8_group_quant_source_work(kernel)
            memory_demand = {role: 0 for role in ("compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            memory_ns = roofline_ns(memory_demand, hardware, work["logical_bytes"])
            for program in work["source_alternatives"]:
                if roofline_ns(program["demand"], hardware, work["logical_bytes"]) > memory_ns:
                    raise NotImplementedError("FP8 quantizer source alternatives are not all memory dominated; bind the scale program")
            return prediction_from_ns(memory_ns, "roofline")
        if kernel.variant == "dsv4_indexer_q_rope_quant":
            work = dsv4_indexer_q_roofline_work(kernel)
            memory_demand = {role: 0.0 for role in (
                "compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            memory_ns = roofline_ns(memory_demand, hardware, work["logical_bytes"])
            # Establish equality of the ideal Roofline result for all source
            # alternatives. Do not choose a backend, min/max a conditional
            # latency range, or treat unknown instructions as proven free.
            for demand in work["source_programs"]["demands_by_backend"].values():
                if roofline_ns(demand, hardware, work["logical_bytes"]) > memory_ns:
                    raise NotImplementedError(
                        "V4 indexer Q source alternatives are not all memory dominated in the mathematical Roofline; "
                        "a source-program binding is required")
            return prediction_from_ns(memory_ns, "roofline")
        if kernel.variant == "vllm_logits_gather_reorder":
            work = vllm_logits_gather_reorder_logical_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware,
                sum(operand["bytes"] for operand in work["operands"])), "roofline")
        if kernel.variant in ("vllm_logits_fp32_cast", "vllm_logits_row_select"):
            work = (vllm_logits_fp32_cast_logical_work(kernel) if kernel.variant == "vllm_logits_fp32_cast"
                    else vllm_logits_row_selection_logical_work(kernel))
            if kernel.variant == "vllm_logits_row_select" and kernel.attributes["index_source"] == "unbound_spec_metadata":
                raise NotImplementedError("target logits row selection index storage is unbound")
            return prediction_from_ns(roofline_ns(work["demand"], hardware,
                sum(operand["bytes"] for operand in work["operands"])), "roofline")
        if kernel.variant in ("mhc_prenorm", "mhc_prenorm_broadcast"):
            work = mhc_prenorm_roofline_work(kernel)
            return prediction_from_ns(
                roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "vocab_parallel_embedding":
            work = vocab_parallel_embedding_logical_work(kernel)
            if work["owned_token_rows"] is None:
                raise NotImplementedError("vocab embedding unsupported: scheduled token ownership is unbound")
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            demand = {role: 0.0 for role in (
                "compute_tensor", "compute_vector", "compute_reduction", "compute_fma", "compute_sfu", "compute_alu")}
            return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")
        if kernel.variant == "vllm_plain_greedy_sample":
            work = vllm_plain_greedy_roofline_work(kernel)
            return prediction_from_ns(
                roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "dsv32_draft_argmax":
            return self.analytical_without_launch(kernel, hardware)
        if kernel.variant in ("kimi_k3_kda_prefill", "kimi_k3_kda_mixed", "kimi_k3_kda_context_prefill"):
            work = {"kimi_k3_kda_prefill": kimi_k3_kda_prefill_logical_work,
                    "kimi_k3_kda_mixed": kimi_k3_kda_mixed_logical_work,
                    "kimi_k3_kda_context_prefill": kimi_k3_kda_context_prefill_logical_work}[kernel.variant](kernel)
            logical_bytes = (work["analytical_logical_bytes"] if kernel.attributes["stage"] == "chunk"
                             else sum(operand["bytes"] for operand in work["operands"]))
            return prediction_from_ns(roofline_ns(work["demand"], hardware, logical_bytes), "roofline")
        if kernel.variant == "kimi_k3_moe_route":
            work = kimi_k3_moe_route_roofline_work(kernel)
            return prediction_from_ns(roofline_ns(work["demand"], hardware, work["logical_bytes"]), "roofline")
        if kernel.variant == "kimi_k3_situ":
            work = kimi_k3_situ_logical_work(kernel)
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            return prediction_from_ns(roofline_ns(work["demand"], hardware, logical_bytes), "roofline")
        if kernel.variant in ("kimi_k3_nope_prefill", "kimi_k3_nope_decode", "kimi_k3_nope_mixed", "kimi_k3_nope_context"):
            work = {
                "kimi_k3_nope_prefill": kimi_k3_nope_prefill_logical_work,
                "kimi_k3_nope_decode": kimi_k3_nope_decode_logical_work,
                "kimi_k3_nope_mixed": kimi_k3_nope_mixed_logical_work,
                "kimi_k3_nope_context": kimi_k3_nope_context_logical_work,
            }[kernel.variant](kernel)
            if work["demand"] is None:
                raise NotImplementedError("K3 context merge LSE value branches and per-pack compiler services remain unbound")
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            return prediction_from_ns(roofline_ns(work["demand"], hardware, logical_bytes), "roofline")
        if kernel.variant in ("kimi_k3_attn_res", "kimi_k3_kda_decode"):
            work = (kimi_k3_attention_residual_logical_work(kernel) if kernel.variant == "kimi_k3_attn_res"
                    else kimi_k3_kda_decode_logical_work(kernel))
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
            return prediction_from_ns(roofline_ns(work["demand"], hardware, logical_bytes), "roofline")
        if kernel.variant == "vllm_embedding_id_widen":
            work = vllm_embedding_id_widen_logical_work(kernel)
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
        elif kernel.variant == "vllm_rejection_logits_materialize":
            work = vllm_rejection_logits_materialization_logical_work(kernel)
            logical_bytes = sum(operand["bytes"] for operand in work["operands"])
        elif kernel.variant in DSV32_DRAFT_MATERIALIZATION_VARIANTS:
            logical_bytes = dsv32_draft_materialization_roofline_bytes(kernel)
        elif kernel.variant in DSV32_DRAFT_INT32_BOOKKEEPING_VARIANTS:
            logical_bytes, int32_operations = dsv32_draft_int32_bookkeeping_roofline_work(kernel)
        else:
            return super().roofline_without_launch(kernel, hardware)
        demand = {role: 0.0 for role in (
            "compute_tensor", "compute_vector", "compute_reduction",
            "compute_fma", "compute_sfu", "compute_alu")}
        demand["compute_alu"] = int32_operations
        return prediction_from_ns(roofline_ns(demand, hardware, logical_bytes), "roofline")

    def forward_resource_input(self, kernel: KernelSpec, hardware):
        return self._forward_resource_input(kernel, hardware)

    def _forward_resource_input(self, kernel: KernelSpec, hardware):
        if ("source_component" in kernel.attributes
                and kernel.attributes["source_component"] == "vllm_0_30_kimi_k3_triton_chunk"):
            return self.resource_input(kernel, hardware)

        from src.kernel.memory_cann_moe_routing import has_cann_moe_range_source,cann_moe_range_source_demands
        if has_cann_moe_range_source(kernel,hardware):
            from src.kernel.memory_access_builder import cann_moe_range_memory_access_program
            cann_moe_range_source_demands(cann_moe_range_memory_access_program(kernel,hardware))
        from src.kernel.memory_cann_moe_routing import has_cann_expert_tokens_source,cann_expert_tokens_source_demands
        if has_cann_expert_tokens_source(kernel,hardware):
            from src.kernel.memory_access_builder import cann_expert_tokens_memory_access_program
            cann_expert_tokens_source_demands(cann_expert_tokens_memory_access_program(kernel,hardware))
        from src.kernel.memory_cann_moe_routing import has_cann_moe_transpose_source,cann_moe_transpose_source_demands
        if has_cann_moe_transpose_source(kernel,hardware):
            from src.kernel.memory_access_builder import elementwise_memory_access_program
            cann_moe_transpose_source_demands(elementwise_memory_access_program(kernel,hardware))
        from src.kernel.memory_cann_moe_routing import has_cann_moe_init_source,cann_moe_init_source_demands
        if has_cann_moe_init_source(kernel,hardware):
            from src.kernel.memory_access_builder import cann_moe_init_memory_access_program
            cann_moe_init_source_demands(cann_moe_init_memory_access_program(kernel,hardware))
        if kernel.variant == 'flash_mla_metadata':
            from src.kernel.memory_access_builder import elementwise_memory_access_program
            from src.kernel.memory_flash_attention import flash_mla_metadata_source_demands
            flash_mla_metadata_source_demands(elementwise_memory_access_program(kernel,hardware))
        from src.kernel.memory_cann_normalization import has_cann_normalization_source, cann_normalization_source_work, cann_normalization_source_demands
        if has_cann_normalization_source(kernel,hardware):
            from src.kernel.memory_access_builder import normalization_memory_access_program, memory_execution_kernel
            execution = memory_execution_kernel(kernel,hardware)
            work = cann_normalization_source_demands(normalization_memory_access_program(execution,hardware))
            with cann_normalization_source_work(execution,work):
                return self._cached_forward_resource_input(kernel,hardware)
        inp, compulsory = self._cached_forward_resource_input(kernel, hardware)
        return _attach_moe_align_shared_atomic_floor(inp, kernel, hardware), compulsory

    def _cached_forward_resource_input(self, kernel: KernelSpec, hardware):
        """Return this exact spec's compact analytical input for one caller."""

        if (self._cached_forward_kernel is kernel
                and self._cached_forward_hardware is hardware):
            if self._cached_forward_value is None:
                raise RuntimeError("Vector forward resource-input cache is incomplete")
            cached_input, cached_compulsory = self._cached_forward_value
            return dataclasses.replace(
                cached_input,
                demand_per_resource=dict(cached_input.demand_per_resource),
                resource_time_overrides_ns=dict(
                    cached_input.resource_time_overrides_ns),
            ), cached_compulsory
        resource_input, compulsory = forward_analytical_resource_input(
            kernel, hardware)
        self._cached_forward_kernel = kernel
        self._cached_forward_hardware = hardware
        self._cached_forward_value = (resource_input, compulsory)
        return resource_input, compulsory

    def oracle_resource_input(self, kernel: KernelSpec, hardware):
        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
            raise NotImplementedError("dense FP16 mathematical work has no native launch")
        # Keep resource_input's expanded source program for contract callers.
        # Oracle only consumes its normalized resource/dependency envelope, so
        # CANN Vector can use the same exact worker-class representation as
        # Forward instead of materializing one identical tile program per
        # physical AIV.
        if (kernel.variant.lower() in {
                    "elementwise", "rmsnorm", "add_rmsnorm"}
                and hardware.kernel_memory_model == "npu_tile"
                and hardware.aic_aiv_separated
                and "cann_tiling_key" in kernel.launch.parameters):
            return self._forward_resource_input(kernel, hardware)
        return self.resource_input(kernel, hardware)

    def midlayer(self, kernel: KernelSpec, hardware):
        if ("mathematical_program" in kernel.attributes
                and kernel.attributes["mathematical_program"] in ("dense_fp16_source_flops_bytes_v1", "dense_bf16_source_flops_bytes_v1")):
            raise NotImplementedError("dense FP16 mathematical work has no native launch")
        # The vLLM-Ascend QKNormRope fusion pass rewrites this pattern at
        # torchair compile time, and capture-limit fallback (NONE) steps
        # still execute the codegen'd fused fx graph: msprof serving traces
        # show one split_qkv_rmsnorm_rope_kernel in both lanes and never a
        # standalone [seq*heads, head_dim] RmsNorm sequence.  Both lanes
        # therefore price through the single fused streaming envelope.
        inp, _ = self._forward_resource_input(kernel, hardware)
        prediction = PerformanceFormula(hardware).predict_kernel(
            _with_graph_regime(inp, kernel))
        return _append_cann_public_rope_index_selects(
            prediction, kernel, hardware)

    def roofline(self, kernel: KernelSpec, hardware):
        if kernel.variant=='moe_transpose' and hardware.kernel_memory_model=='npu_tile':
            from src.kernel.memory_cann_moe_routing import is_cann_transpose_alias
            if is_cann_transpose_alias(kernel):return _cann_transpose_alias_prediction(kernel,hardware,'roofline')
        inp, compulsory = self._forward_resource_input(kernel, hardware)
        return prediction_from_ns(
            roofline_ns(inp.demand_per_resource, hardware, compulsory), "roofline")

    def pipeweave(self, kernel: KernelSpec, hardware, *, model_hardware=None):
        if kernel.variant == "silu" and kernel.attributes["swiglu_limit"] is not None:
            raise NotImplementedError("clamped SiLU supports Roofline only")
        variant = kernel.variant.lower()
        if variant == "dsv4_moe_route":
            raise NotImplementedError("V4 source routing supports Roofline only")
        if variant in ("rmsnorm", "add_rmsnorm"):
            from src.kernel.predictors.pipeweave_adapter import predict_norm
            return predict_norm(
                kernel, hardware, model_hardware=model_hardware)
        # PipeWeave's siluandmul model covers the SiLU-and-multiply operator
        # itself, so both the dense launch and the fused-MoE launch of that
        # same operator belong in its domain.  Routing, align, sort and reduce
        # launches have no PipeWeave model and fall through to the base class.
        if variant not in (
                "activation", "silu", "moe_act_and_mul", "moe_swiglu"):
            return super().pipeweave(
                kernel, hardware, model_hardware=model_hardware)
        from src.kernel.predictors.pipeweave_adapter import predict_vector_activation
        return predict_vector_activation(
            kernel, hardware, model_hardware=model_hardware)
